#!/usr/bin/env python3
# =====================================================================
#  apply_exit_latency.py  —  fence EXIT_LATENCY_20261115
#  REQUIRES v11.8.0 (all six assurance scripts of 15 Nov 2026).
#
#  ⚠ LIVE ORDER PATH — makes exits FASTER; changes no decision.
#
#  1. Every exit of a leg that has a GTT waited a FIXED 1.5 s after cancelling
#     the GTT, before it checked the cancel and placed the exit order
#     (ZerodhaOrderExecutor.cancel_gtt_verified: time.sleep(1.5)). Timberwolf:
#     1.5 s on every exit. Icarus: 1.5 s per short leg, one after the other
#     (3 s before the second buy-back at the 09:16 square-off).
#     → the GTT list is now checked at 0.25 / 0.6 / 1.0 / 1.5 s and the exit
#       goes as soon as the broker shows the cancel. Never later than before:
#       a GTT that stays armed or a list that cannot be read takes the same
#       total time and the same number of broker calls as in v11.8.0.
#  2. v11.8.0 added one broker call to every Timberwolf exit (a GTT status
#     read before the cancel, to learn whether the stop had already fired).
#     → that is now read from what the verified cancel just saw
#       (gtt_last_state) — no extra call.
#  3. v11.8.0 wrote the "orders placed by this app" day file synchronously
#     after each order. → written by a background thread; the order path
#     only updates memory (measured: ~30 microseconds per order).
#
#   execution/zerodha_executor.py     polling verify, gtt_last_state
#   execution/execution_router.py     forwards gtt_last_state
#   execution/broker_truth.py         background writer for the day file
#   engine/tma2/tma2_trade_manager.py no extra GTT status read
#   engine/test_fleet_live.py         the fake broker gets gtt_last_state
#   execution/test_gtt_verify_strict.py   one expectation: short lag needs no 2nd cancel
#   execution/test_exit_latency.py    NEW — 9 checks on the real executor, fake clock
#   engine/test_order_path_budget.py  NEW — broker round trips per entry / exit
#                                     held to the v11.7.9 numbers, all four strategies
#
#  Run ONLY this script, outside market hours:
#     cd ~/dev/scalp-app && python3 apply_exit_latency.py
#  Options: --repo PATH  --skip-tests  --allow-dirty  --rollback
#  Then: ./desktop/build-scalp.sh both, restart the app.
# =====================================================================
import base64, hashlib, json, os, py_compile, shutil, subprocess, sys, tempfile, zlib

FENCE = "EXIT_LATENCY_20261115"
ITEMS = json.loads(r'''[{"path": "backend/app/engine/test_fleet_live.py", "orig": "b2d2d94026b8e1e2ab6b9ecba765261be4cdfccc9336ae3de89a4ee5fd5000d6", "new": "db9827d82b819f82e42fd0fc2729a3e144b533632de9da0a06228622161822df", "blob": ""}, {"path": "backend/app/engine/test_order_path_budget.py", "orig": null, "new": "a1b77dc28e9cf4df9f526a74cd7b42f6d7c1775aee0e64f3c897b5fd87787b97", "blob": ""}, {"path": "backend/app/engine/tma2/tma2_trade_manager.py", "orig": "3162d214aeeed162ca654f394872e8eb230eb60c57407e7408b35391d8eac371", "new": "d6800470f414067ce7d1551082b33d2f02cc0f1511cd9289c37bd2ede969a0a0", "blob": ""}, {"path": "backend/app/execution/broker_truth.py", "orig": "99f56bf304b4e265ea00a9187c6ed99d4a3d4b8bffb6f8942bb3c6b50be40c5b", "new": "3b2b47e43f0b2bed645a47940df590c73ad60fab3ac75b9cfb1abd01eab36926", "blob": ""}, {"path": "backend/app/execution/execution_router.py", "orig": "14794a18697893bf424c38acb5a546153de84f0bfc6b71259bbc1b4445a42c5b", "new": "a1ad7c0eb136e31297551430f44224b296302ebceeb20e0bb9fe1173ac368b5d", "blob": ""}, {"path": "backend/app/execution/test_exit_latency.py", "orig": null, "new": "aedb0e3998e477e585456aa6ab46cd314f46b666016ad914a4955299bb6429c3", "blob": ""}, {"path": "backend/app/execution/test_gtt_verify_strict.py", "orig": "a6508bb881baf9024b6311cadab151640d1fd1e9daa3e8b045a970cf6a1d568a", "new": "fdd9137eb54698dd6dfe8889854fa77a2ba54f8282f155332158e91c9966fcfe", "blob": ""}, {"path": "backend/app/execution/zerodha_executor.py", "orig": "6af0ded61db39acb0e032444a0d5d5c8f8ef89eaabf840172637032aafdd886d", "new": "1edb2324b96a3741efe1cc7a91d78a684094cf1e8ee67aabca89d9eacd27ae90", "blob": ""}]''')
BUILD_COPIES = {"backend/": "desktop/src-tauri/backend/", "frontend/": "desktop/src-tauri/frontend/"}
TESTS = [         "app/execution/test_exit_latency.py",
         "app/engine/test_order_path_budget.py",
         "app/execution/test_gtt_verify_strict.py",
         "app/execution/test_broker_truth.py",
         "app/execution/test_execution_router_contract.py",
         "app/engine/test_fleet_adversarial.py",
         "app/engine/test_fleet_live.py",
         "app/engine/ic/test_ic_gtt_strict.py",
         "app/engine/tma2/test_tma2_e2e.py",
         "app/engine/tma2/test_tma2_exit_paths.py",
         "app/engine/tma2/test_tma_fill_truth.py",
         "app/engine/tma2/test_tma_gap_close.py"
]


def sha(b):
    return hashlib.sha256(b).hexdigest()


def say(m):
    print(m, flush=True)


def die(m):
    say(f"\n✗ ABORTED — {m}\n  Nothing was changed.")
    sys.exit(1)


args = sys.argv[1:]
repo = os.path.abspath(os.path.expanduser(args[args.index("--repo") + 1])) if "--repo" in args else os.getcwd()
if not os.path.isdir(os.path.join(repo, "backend", "app")):
    alt = os.path.expanduser("~/dev/scalp-app")
    if os.path.isdir(os.path.join(alt, "backend", "app")):
        repo = alt
    else:
        die(f"{repo} is not the scalp-app repo (no backend/app) — pass --repo PATH")
say(f"repo: {repo}\nfence: {FENCE}")

# ── prerequisite: v11.8.0 (apply_strict_reads_all.py)
if "--rollback" not in args:
    _pf = os.path.join(repo, *['backend', 'app', 'execution', 'broker_truth.py'])
    if not os.path.exists(_pf) or 'STRICT_READS_ALL_20261115' not in open(_pf, encoding="utf-8").read():
        die("needs v11.8.0 (apply_strict_reads_all.py) — this script builds on it")


def targets():
    """(item, absolute path, is_build_copy)"""
    out = []
    for it in ITEMS:
        out.append((it, os.path.join(repo, it["path"]), False))
        for a, b in BUILD_COPIES.items():
            if it["path"].startswith(a):
                p = os.path.join(repo, b + it["path"][len(a):])
                if os.path.isdir(os.path.dirname(p)):
                    out.append((it, p, True))
    return out


# ── rollback mode ────────────────────────────────────────────────────
if "--rollback" in args:
    n = 0
    for it, p, _ in targets():
        bak = p + ".bak-" + FENCE
        if os.path.exists(bak):
            shutil.copy2(bak, p)
            os.remove(bak)
            n += 1
        elif it["orig"] is None and os.path.exists(p):
            with open(p, "rb") as f:
                if sha(f.read()) == it["new"]:
                    os.remove(p)
                    n += 1
    say(f"rolled back {n} file(s)")
    sys.exit(0)

# ── 1. state of every target ─────────────────────────────────────────
plan, done, skipped = [], 0, []
for it, p, build in targets():
    cur = open(p, "rb").read() if os.path.exists(p) else None
    cs = sha(cur) if cur is not None else None
    rel = os.path.relpath(p, repo)
    if cs == it["new"]:
        done += 1
        continue
    if cs == it["orig"]:
        plan.append((it, p, cur, build))
        continue
    if build:
        skipped.append(rel)              # a stale build copy — the build re-syncs it
        continue
    if cur is None:
        die(f"{rel} is missing")
    die(f"{rel} differs from GitHub main and from the patched version — local edits? "
        f"(commit/stash them or pull main, then re-run)")
if not plan:
    say(f"✓ already applied ({done} file(s) carry {FENCE}) — nothing to do")
    sys.exit(0)

# ── 2. git status: an uncommitted change on a target is a stop sign ──
if "--allow-dirty" not in args:
    try:
        rels = [os.path.relpath(p, repo) for _, p, _, b in plan if not b]
        st = subprocess.run(["git", "status", "--porcelain", "--"] + rels, cwd=repo,
                            capture_output=True, text=True, timeout=30).stdout
        dirty = [l for l in st.splitlines() if l[:2].strip() and not l.startswith("??")]
        if dirty:
            die("uncommitted changes on target files:\n  " + "\n  ".join(dirty) + "\n  (re-run with --allow-dirty to override)")
    except FileNotFoundError:
        say("  (git not found — skipping the status check)")

# ── 3. decode + compile every payload before writing anything ───────
tmp = tempfile.mkdtemp(prefix="exit_latency_")
blobs = {}
for it in ITEMS:
    b = zlib.decompress(base64.b64decode(it["blob"]))
    if sha(b) != it["new"]:
        die(f"payload for {it['path']} is corrupt")
    blobs[it["path"]] = b
    if it["path"].endswith(".py"):
        f = os.path.join(tmp, os.path.basename(it["path"]))
        open(f, "wb").write(b)
        try:
            py_compile.compile(f, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"payload {it['path']} does not compile: {e}")
say(f"payloads verified and compiled ({len(ITEMS)} files)")

# ── 4. write, all or nothing ─────────────────────────────────────────
written = []


def restore():
    for p, old in reversed(written):
        try:
            if old is None:
                os.remove(p)
            else:
                open(p, "wb").write(old)
            bak = p + ".bak-" + FENCE
            if os.path.exists(bak):
                os.remove(bak)
        except Exception as e:
            say(f"  !! could not restore {p}: {e}")


try:
    for it, p, cur, build in plan:
        if cur is not None:
            open(p + ".bak-" + FENCE, "wb").write(cur)
        t = p + ".tmp-" + FENCE
        open(t, "wb").write(blobs[it["path"]])
        os.replace(t, p)
        written.append((p, cur))
        say(f"  wrote {os.path.relpath(p, repo)}{'  (build copy)' if build else ''}")
except Exception as e:
    restore()
    die(f"write failed ({e!r}) — everything restored")
for s_ in skipped:
    say(f"  skipped stale build copy {s_} (the next build re-syncs it)")

# ── 5. tests ─────────────────────────────────────────────────────────
backend = os.path.join(repo, "backend")
py = next((c for c in (os.path.join(backend, "venv", "bin", "python"), os.path.join(backend, ".venv", "bin", "python"),
                       os.path.join(repo, "venv", "bin", "python"), os.path.join(repo, ".venv", "bin", "python"))
           if os.path.exists(c)), sys.executable)
if "--skip-tests" in args:
    say("tests skipped (--skip-tests)")
else:
    say(f"running tests with {py}")
    env = dict(os.environ, PYTHONPATH=backend, SCALP_TEST_MODE="1")
    failed, envmiss = [], []
    for t in TESTS:
        if not os.path.exists(os.path.join(backend, t)):
            continue
        try:
            r = subprocess.run([py, t], cwd=backend, env=env, capture_output=True, text=True, timeout=900)
            outp = (r.stdout or "") + (r.stderr or "")
        except subprocess.TimeoutExpired:
            r, outp = None, "timeout"
        last = (outp.strip().splitlines() or [""])[-1]
        if r is not None and r.returncode == 0:
            say(f"  ✓ {t}  {last}")
        elif "ModuleNotFoundError" in outp and "No module named 'app" not in outp:
            envmiss.append(t)
            say(f"  ? {t}  could not run here: {last}")
        else:
            failed.append(t)
            say(f"  ✗ {t}\n" + "\n".join("      " + l for l in outp.strip().splitlines()[-25:]))
    if failed:
        restore()
        die("tests failed: " + ", ".join(failed) + " — every file restored")
    if envmiss:
        say("  note: some suites need the backend's Python packages; re-run them with that Python")

shutil.rmtree(tmp, ignore_errors=True)
say(f"\n✓ {FENCE} applied ({len(written)} file(s)). Next: ./desktop/build-scalp.sh both, then restart the app.")
say("  Undo: python3 apply_exit_latency.py --rollback")
